campaign.scale:
// scale: out = s*a -- independent iterations -> SAFE parallel (~16 B/elem).
// Seeded deterministically (mirrors rust_twins::scale_inputs) so the checked
// element is a nonzero signed fraction, not the all-zero vacuity.
fn main() {
    let n = 33554432;
    let a: [f64] = zeros(n);
    let out: [f64] = zeros(n);
    for i in 0..n {
        a[i] = ((i * 13 + 5) % 199) as f64 / 7.0 - 12.0;
    }
    for i in 0..n {
        out[i] = a[i] * 5.0;
    }
    print(out[42]);
}

campaign.saxpy:
// saxpy: y = s*x + y -- memory-bound streaming kernel (~24 B/elem moved).
// Seeded deterministically (sign/fraction mix) so no execution pass can fold
// the loop or pass a parity check vacuously; mirrors rust_twins::saxpy_inputs.
fn main() {
    let n = 33554432;
    let x: [f64] = zeros(n);
    let y: [f64] = zeros(n);
    for i in 0..n {
        x[i] = ((i * 17 + 3) % 251) as f64 / 17.0 - 4.0;
        y[i] = ((i * 29 + 11) % 241) as f64 / 19.0 - 5.0;
    }
    let s = 2.5;
    for i in 0..n {
        y[i] = s * x[i] + y[i];
    }
    print(y[7]);
}

campaign.dot_reduction:
// dot product: +-reduction over products of two arrays (FP sum reassociates).
// Both operands are seeded with sign-mixed fractions (mirroring
// rust_twins::dot_inputs) so partial products cancel — a zero-initialized
// pair would make every broken kernel print the "right" 0.
fn main() {
    let n = 16777216;
    let a: [f64] = zeros(n);
    let b: [f64] = zeros(n);
    for i in 0..n {
        a[i] = ((i * 7 + 1) % 97) as f64 / 9.0 - 4.0;
        b[i] = ((i * 11 + 2) % 89) as f64 / 11.0 - 3.0;
    }
    let dot = 0.0;
    for i in 0..n {
        dot = dot + a[i] * b[i];
    }
    print(dot);
}

campaign.minmax_reduction:
// min + max in one loop: order-independent reductions -> bit-exact validation
fn main() {
    let n = 16777216;
    let a: [f64] = zeros(n);
    let lo = 1.0e300;
    let hi = 0.0;
    for i in 0..n {
        let sq = a[i] * a[i];
        lo = min(lo, a[i]);
        hi = max(hi, sq);
    }
    print(lo);
    print(hi);
}

campaign.count_primes_sieve:
// Strided sieve: outer loop sequential (branch on composite), inner sweep
// writes disjoint strided indices -> inner loop is DOALL. Expressed with an
// affine subscript because HELIX has no step clause.
fn main() {
    let n = 10000000;
    let composite: [bool] = zeros(n);
    let count = 0;
    for i in 2..n {
        if !composite[i] {
            count = count + 1;
            let start = i + i;
            let sweeps = (n - start + i - 1) / i;
            for k in 0..sweeps {
                composite[start + k * i] = true;
            }
        }
    }
    print(count);
}

campaign.recurrence_reject:
// Distance-1 recurrence: RAW flow dependence at distance 1 through 'a'.
// NOT a reduction (intermediate stores are observed later), so the
// dependence engine MUST reject parallelization; we still measure the
// sequential run to show the cost of refusal is zero.
fn main() {
    let n = 10000000;
    let a: [i64] = zeros(n);
    a[0] = 1;
    for i in 1..n {
        a[i] = a[i - 1] + 1;
    }
    print(a[n - 1]);
}

