campaign.jacobi_2d:
// 5-point Jacobi stencil, flattened SIZE x SIZE: interior rows independent
// within a sweep -> level-2 DOALL. Consts live at TOP LEVEL per the frozen
// grammar (they are scalars, which is legal there).
const SIZE: i64 = 4096;
const ITER: i64 = 10;

fn main() {
    let n = SIZE * SIZE;
    let cur: [f64] = zeros(n);
    let next: [f64] = zeros(n);
    cur[SIZE * (SIZE / 2) + SIZE / 2] = 256.0;
    for k in 0..ITER {
        for i in 1..SIZE - 1 {
            let base = i * SIZE;
            for j in 1..SIZE - 1 {
                next[base + j] = 0.25 * (cur[base + j - 1] + cur[base + j + 1]
                                       + cur[base - SIZE + j] + cur[base + SIZE + j]);
            }
        }
        for i in 0..n {
            cur[i] = next[i];
        }
    }
    print(cur[SIZE * (SIZE / 2) + SIZE / 2]);
}

campaign.matmul:
// C = A*B, naive i-j-k: outer-i rows of C are independent (DOALL), inner-k
// is a classic +-reduction into acc. Compared only against its own modes.
const N: i64 = 512;

fn main() {
    let nn = N * N;
    let a: [f64] = zeros(nn);
    let b: [f64] = zeros(nn);
    let c: [f64] = zeros(nn);
    for i in 0..nn {
        a[i] = (i % 97) as f64 * 0.5;
        b[i] = ((i * 7) % 89) as f64 * 0.25;
    }
    for i in 0..N {
        let ibase = i * N;
        for j in 0..N {
            let acc = 0.0;
            for k in 0..N {
                acc = acc + a[ibase + k] * b[k * N + j];
            }
            c[ibase + j] = acc;
        }
    }
    print(c[N * (N / 2) + N / 2]);
}

